//! `pgbr-ffi` is the C ABI surface consumed by the legacy C build during the C->Rust migration.
//!
//! Each phase moves an additional `extern "C"` shim into this crate. The header `pgbr_ffi.h` is
//! regenerated by cbindgen from this crate at build time.
//!
//! Every C-callable function defined here goes through the [`with_panic_guard`] helper so panics
//! crossing the FFI boundary are caught and translated into a typed [`pgbr_error::ErrorType`]
//! value rather than aborting the process. C callers always observe well-defined return values
//! and can read the panic message via [`pgbr_last_error_msg`].

use core::ffi::{CStr, c_char};
use std::ffi::CString;
use std::sync::atomic::{AtomicPtr, Ordering};

use pgbr_error::{Error, ErrorType, clear_last_error, last_error_code, last_error_message, set_last_error};

/// Version string of the embedded Rust FFI shim, tracking `Cargo.toml`'s workspace version.
///
/// Baked into the static archive and returned to C as a NUL-terminated UTF-8 string.
// SAFETY: `CARGO_PKG_VERSION` is provided by Cargo and is guaranteed not to contain interior
// NULs; appending a single `\0` produces a well-formed C string.
const PGBR_FFI_VERSION: &CStr = unsafe { CStr::from_bytes_with_nul_unchecked(concat!(env!("CARGO_PKG_VERSION"), "\0").as_bytes()) };

/// Default value an `extern "C"` shim returns after a panic crosses its boundary.
///
/// Implemented for every type used as a return value from a [`with_panic_guard`]-wrapped FFI
/// values are deliberately chosen so a C caller observing them and inspecting
/// [`pgbr_last_error_code`] can distinguish a panic (`Unknown` = 125) from a clean operation.
pub trait FfiPanicReturn {
    /// Sentinel value returned when the wrapped Rust code panics.
    fn ffi_panic_return() -> Self;
}

impl FfiPanicReturn for () {
    fn ffi_panic_return() {}
}

impl FfiPanicReturn for i32 {
    fn ffi_panic_return() -> Self {
        -1
    }
}

impl<T> FfiPanicReturn for *const T {
    fn ffi_panic_return() -> Self {
        core::ptr::null()
    }
}

impl<T> FfiPanicReturn for *mut T {
    fn ffi_panic_return() -> Self {
        core::ptr::null_mut()
    }
}

/// Run `body` while protecting the FFI boundary from a Rust panic.
///
/// If the body panics, the panic is recorded as the thread's last error
/// (category [`pgbr_error::ErrorType::Unknown`]) and the function returns the type's
/// [`FfiPanicReturn`] sentinel. Without this guard, a panic crossing the FFI boundary is
/// undefined behaviour.
///
/// The guard does **not** clear the thread-local error slot. Reader-style shims like
/// `pgbr_last_error_code` would otherwise erase the very value the C caller is trying to read.
/// A fallible Rust shim that wants to start from a clean slate should call
/// [`pgbr_error::clear_last_error`] inside the body before doing work.
fn with_panic_guard<R, F>(body: F) -> R
where
    R: FfiPanicReturn,
    F: FnOnce() -> R,
{
    std::panic::catch_unwind(std::panic::AssertUnwindSafe(body)).unwrap_or_else(|_| {
        record_panic_as_last_error();
        R::ffi_panic_return()
    })
}

/// Internal helper used by [`with_panic_guard`] when `catch_unwind` traps a panic. Records a
/// typed `Unknown` error so the C caller can read the panic via [`pgbr_last_error_msg`].
fn record_panic_as_last_error() {
    set_last_error(Error::new(ErrorType::Unknown, "rust panic crossed FFI boundary"));
}

/// Returns a pointer to a static, NUL-terminated UTF-8 string identifying the Rust FFI shim
/// version. The pointer is valid for the lifetime of the process and must not be freed.
#[unsafe(no_mangle)]
pub extern "C" fn pgbr_version() -> *const c_char {
    with_panic_guard(|| PGBR_FFI_VERSION.as_ptr())
}

/// Numeric code of the calling thread's last error, or `0` if no error is set.
///
/// Mirrors the C `errorTypeCode` numbering. Reads the same thread-local slot populated by Rust
/// shims via `pgbr_error::set_last_error` and by the C-side helpers below.
#[unsafe(no_mangle)]
pub extern "C" fn pgbr_last_error_code() -> i32 {
    with_panic_guard(last_error_code)
}

/// Pointer to a NUL-terminated UTF-8 message of the calling thread's last error, or `null` if no
/// error is set.
///
/// The returned pointer is valid until the next call into `pgbr_last_error_*` on the same thread
/// (any of `pgbr_last_error_set`, `pgbr_last_error_clear`, `pgbr_last_error_take_code`). The
/// caller must not free it.
#[unsafe(no_mangle)]
pub extern "C" fn pgbr_last_error_msg() -> *const c_char {
    with_panic_guard(last_error_message)
}

/// Sets the calling thread's last error to the given typed `code` and `message_utf8` C string.
///
/// Returns `0` on success, `-1` if `code` is not part of the shared error table or
/// `message_utf8` is null or not valid UTF-8. On `-1`, the existing thread-local error is left
/// untouched.
///
/// # Safety
///
/// `message_utf8` must point to a NUL-terminated, valid UTF-8 byte sequence readable for the
/// duration of the call.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pgbr_last_error_set(code: i32, message_utf8: *const c_char) -> i32 {
    with_panic_guard(|| {
        let Some(error_type) = ErrorType::from_code(code) else {
            return -1;
        };
        if message_utf8.is_null() {
            return -1;
        }
        // SAFETY: caller guarantees `message_utf8` is NUL-terminated and readable.
        let cstr = unsafe { CStr::from_ptr(message_utf8) };
        let Ok(message) = cstr.to_str() else {
            return -1;
        };
        set_last_error(Error::new(error_type, message));
        0
    })
}

/// Removes the calling thread's last error and returns its numeric code.
///
/// Returns `0` if no error was set. The associated message becomes invalid as soon as this
/// function returns.
#[unsafe(no_mangle)]
pub extern "C" fn pgbr_last_error_take_code() -> i32 {
    with_panic_guard(|| pgbr_error::take_last_error().map_or(0, |e| e.code()))
}

/// Clears the calling thread's last error.
#[unsafe(no_mangle)]
pub extern "C" fn pgbr_last_error_clear() {
    with_panic_guard(clear_last_error);
}

/// Logging callback registered by the C side to receive every Rust-originated log line.
///
/// The first argument is a numeric log level matching the C `LogLevel` enum (off=0, assert=1,
/// error=2, protocol=3, warn=4, info=5, detail=6, debug=7, trace=8). The second argument is a
/// pointer to a NUL-terminated UTF-8 message valid only during the call.
pub type PgbrLogCallback = unsafe extern "C" fn(level: i32, message_utf8: *const c_char);

static LOG_CALLBACK_RAW: AtomicPtr<()> = AtomicPtr::new(core::ptr::null_mut());

/// Registers a callback the Rust side invokes for every log line.
///
/// The callback is stored atomically and may be invoked from any thread. Replacing it is atomic
/// with respect to in-flight calls; in-flight calls always observe either the previous or the new
/// pointer, never a torn value. To stop receiving callbacks, use [`pgbr_log_clear_callback`].
///
/// # Safety
///
/// `callback` must be a valid `extern "C"` function pointer that remains live for as long as it
/// can be reached by the Rust side. The C side guarantees this by pointing to a static function.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pgbr_log_set_callback(callback: PgbrLogCallback) {
    with_panic_guard(|| {
        let raw: *mut () = callback as *mut ();
        LOG_CALLBACK_RAW.store(raw, Ordering::SeqCst);
    });
}

/// Removes any logging callback previously registered through [`pgbr_log_set_callback`]. After
/// this call, [`pgbr_log`] is a no-op until a new callback is installed.
#[unsafe(no_mangle)]
pub extern "C" fn pgbr_log_clear_callback() {
    with_panic_guard(|| {
        LOG_CALLBACK_RAW.store(core::ptr::null_mut(), Ordering::SeqCst);
    });
}

/// Forwards a log message to the registered callback, if any. Drops the message silently if no
/// callback has been set or if the message contains an interior NUL that cannot be removed.
///
/// Internal API used by other workspace crates; not exposed through cbindgen because it accepts
/// Rust types.
pub fn pgbr_log(level: i32, message: &str) {
    let raw = LOG_CALLBACK_RAW.load(Ordering::SeqCst);
    if raw.is_null() {
        return;
    }
    // SAFETY: the only writer of LOG_CALLBACK_RAW is `pgbr_log_set_callback`, which stores either
    // null or a `PgbrLogCallback` cast to `*mut ()`. We've checked for null above, so the pointer
    // is a valid function pointer when the callback was registered. Replacement is atomic.
    let callback: PgbrLogCallback = unsafe { core::mem::transmute(raw) };

    let cleaned: Vec<u8> = message.bytes().filter(|b| *b != 0).collect();
    let Ok(cstring) = CString::new(cleaned) else {
        return;
    };
    // SAFETY: the registered callback abides by extern "C" calling conventions and accepts a
    // pointer to a NUL-terminated UTF-8 buffer valid for the duration of the call.
    unsafe { callback(level, cstring.as_ptr()) };
}

/// Numeric mapping of the C `LogLevel` enum used by [`pgbr_log`] and [`PgbrLogCallback`]. The
/// values match the C side so a Rust producer and a C consumer can share a single integer.
#[repr(i32)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum LogLevel {
    /// Logging disabled.
    Off = 0,
    /// Programmer assertion violation; treated as fatal by the C side.
    Assert = 1,
    /// Recoverable error.
    Error = 2,
    /// Protocol-level diagnostic.
    Protocol = 3,
    /// Warning.
    Warn = 4,
    /// Informational message.
    Info = 5,
    /// Detailed informational message.
    Detail = 6,
    /// Debug-level diagnostic.
    Debug = 7,
    /// Trace-level diagnostic.
    Trace = 8,
}

#[cfg(test)]
#[allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]
mod tests {
    use super::*;

    fn cstr(s: &str) -> CString {
        CString::new(s).unwrap()
    }

    #[test]
    fn version_is_non_empty_and_matches_cargo() {
        let ptr = pgbr_version();
        assert!(!ptr.is_null());
        // SAFETY: pgbr_version() returns a pointer to PGBR_FFI_VERSION, a 'static CStr.
        let result = unsafe { CStr::from_ptr(ptr) };
        let rust_str = result.to_str().expect("ffi version is utf-8");
        assert_eq!(rust_str, env!("CARGO_PKG_VERSION"));
        assert!(!rust_str.is_empty());
    }

    #[test]
    fn error_set_and_read_round_trip() {
        pgbr_last_error_clear();
        let msg = cstr("disk full while writing manifest");
        // SAFETY: msg owns a valid NUL-terminated UTF-8 buffer for the duration of the call.
        let rc = unsafe { pgbr_last_error_set(94, msg.as_ptr()) };
        assert_eq!(rc, 0);
        assert_eq!(pgbr_last_error_code(), 94);

        let msg_ptr = pgbr_last_error_msg();
        assert!(!msg_ptr.is_null());
        // SAFETY: msg_ptr is the cached CString in the thread-local slot; valid until next
        // mutation.
        let read = unsafe { CStr::from_ptr(msg_ptr) }.to_str().unwrap();
        assert_eq!(read, "disk full while writing manifest");

        let taken = pgbr_last_error_take_code();
        assert_eq!(taken, 94);
        assert_eq!(pgbr_last_error_code(), 0);
        assert!(pgbr_last_error_msg().is_null());
    }

    #[test]
    fn error_set_rejects_unknown_code_and_null_message() {
        pgbr_last_error_clear();
        let msg = cstr("ignored");

        // SAFETY: msg is a valid NUL-terminated buffer.
        let rc = unsafe { pgbr_last_error_set(7777, msg.as_ptr()) };
        assert_eq!(rc, -1);
        assert_eq!(pgbr_last_error_code(), 0);

        // SAFETY: explicit null pointer is allowed by the function's documented contract.
        let rc_null = unsafe { pgbr_last_error_set(94, std::ptr::null()) };
        assert_eq!(rc_null, -1);
        assert_eq!(pgbr_last_error_code(), 0);
    }

    #[test]
    fn panic_guard_does_not_auto_clear_so_readers_observe_state() {
        // The guard must not erase the slot on entry — otherwise reader shims would always return
        // 0 / null when called immediately after a writer.
        set_last_error(Error::new(ErrorType::Memory, "still here"));
        assert_eq!(pgbr_last_error_code(), 94);
        // pgbr_last_error_msg is also wrapped; if the guard auto-cleared, the pointer would be
        // null after this call.
        assert!(!pgbr_last_error_msg().is_null());
        pgbr_last_error_clear();
    }

    #[test]
    fn panic_guard_catches_panics_and_records_unknown_error() {
        let rc: i32 = with_panic_guard(|| panic!("boom"));
        assert_eq!(rc, -1);
        assert_eq!(pgbr_last_error_code(), 125);
        let msg_ptr = pgbr_last_error_msg();
        assert!(!msg_ptr.is_null());
        // SAFETY: pointer comes from the thread-local slot we just populated.
        let msg = unsafe { CStr::from_ptr(msg_ptr) }.to_str().unwrap();
        assert!(msg.contains("rust panic"));
        pgbr_last_error_clear();
    }

    static CALLBACK_HITS: std::sync::atomic::AtomicI32 = std::sync::atomic::AtomicI32::new(0);
    static LAST_LEVEL: std::sync::atomic::AtomicI32 = std::sync::atomic::AtomicI32::new(-99);

    extern "C" fn capture_callback(level: i32, _msg: *const c_char) {
        CALLBACK_HITS.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
        LAST_LEVEL.store(level, std::sync::atomic::Ordering::SeqCst);
    }

    #[test]
    fn log_callback_round_trip() {
        CALLBACK_HITS.store(0, std::sync::atomic::Ordering::SeqCst);
        LAST_LEVEL.store(-99, std::sync::atomic::Ordering::SeqCst);

        // SAFETY: capture_callback is a static extern "C" function valid for the lifetime of the
        // process.
        unsafe { pgbr_log_set_callback(capture_callback) };
        pgbr_log(LogLevel::Warn as i32, "something happened");
        pgbr_log(LogLevel::Info as i32, "another");
        pgbr_log_clear_callback();
        pgbr_log(LogLevel::Error as i32, "should be dropped");

        assert_eq!(CALLBACK_HITS.load(std::sync::atomic::Ordering::SeqCst), 2);
        assert_eq!(LAST_LEVEL.load(std::sync::atomic::Ordering::SeqCst), LogLevel::Info as i32);
    }
}
